const CSS_LESSONS = [
  {id:"css-intro",level:1,title:"CSS : le style du Web",minutes:12,objective:"Comprendre le rôle de CSS, les trois façons de l'ajouter et la liaison HTML/CSS.",
    explanation:["HTML décrit la structure et le sens du contenu. CSS décrit sa présentation : couleurs, dimensions, espacements et mise en page.","Dans un vrai projet, une feuille externe liée avec <link> est généralement préférable : elle sépare le contenu de la présentation et se réutilise sur plusieurs pages."],
    code:'<link rel="stylesheet" href="style.css">\n\n/* style.css */\nh1 {\n  color: #7c3aed;\n}',
    details:["Le navigateur charge d'abord le HTML puis applique les règles CSS correspondantes.","Une règle peut cibler plusieurs éléments partageant le même sélecteur.","Le style inline existe, mais devient vite difficile à maintenir."],
    mistakes:["Oublier de lier style.css dans le HTML.","Mettre tout le CSS dans style= alors qu'une classe serait réutilisable."],shortcut:{win:"Ctrl + P",mac:"Cmd + P",text:"Ouvrir rapidement style.css dans VS Code."},studio:"css-intro"},
  {id:"css-syntax",level:1,title:"Anatomie d'une règle CSS",minutes:14,objective:"Identifier sélecteur, propriété, valeur, déclaration et bloc.",
    explanation:["Une règle CSS commence par un sélecteur, puis un bloc entre accolades.","Chaque déclaration associe une propriété à une valeur et se termine généralement par un point-virgule."],
    code:'p {\n  color: #1d4ed8;\n  font-size: 18px;\n}',details:["p est le sélecteur.","color et font-size sont des propriétés.","#1d4ed8 et 18px sont des valeurs."],mistakes:["Oublier les deux-points entre propriété et valeur.","Écrire width: 300 sans unité pour une longueur qui en exige une."],shortcut:{win:"Shift + Alt + F",mac:"Shift + Option + F",text:"Formater proprement le fichier CSS."},studio:"css-syntax"},
  {id:"css-selectors",level:1,title:"Sélecteurs : cibler les bons éléments",minutes:16,objective:"Utiliser élément, classe, ID et combinaison simple sans sur-cibler.",
    explanation:["Le sélecteur d'élément cible toutes les balises du même type. Une classe cible les éléments portant cette classe et se réutilise.","Un ID est unique dans la page. Pour le style courant, préfère souvent les classes : elles composent mieux une interface."],
    code:'p { color: #475569; }\n.card { padding: 16px; }\n#hero { background: #eef2ff; }\n.card h2 { color: #312e81; }',details:[".card cible class=card.","#hero cible id=hero.",".card h2 cible les h2 situés dans .card."],mistakes:["Oublier le point devant une classe.","Utiliser un ID partout pour styliser des composants réutilisables."],shortcut:{win:"Ctrl + F",mac:"Cmd + F",text:"Rechercher un nom de classe dans le fichier."},studio:"css-selectors"},
  {id:"css-colors",level:1,title:"Couleurs modernes",minutes:15,objective:"Utiliser noms, HEX, RGB/HSL et transparence de façon lisible.",
    explanation:["CSS accepte plusieurs formats de couleur. HEX est compact, RGB décrit les canaux rouge/vert/bleu et HSL est pratique pour raisonner en teinte, saturation et luminosité.","La transparence peut être exprimée avec rgba(), hsla() ou les syntaxes modernes avec / alpha."],
    code:'.title { color: #0f172a; }\n.badge { background: rgb(219 234 254); }\n.panel { border-color: hsl(221 83% 53% / .35); }',details:["#RRGGBB contient deux chiffres hexadécimaux par canal.","HSL peut être pratique pour décliner un thème.","Le contraste compte plus que le format choisi."],mistakes:["Choisir deux couleurs jolies mais illisibles ensemble.","Utiliser trop de couleurs d'accent différentes."],shortcut:{win:"Ctrl + Shift + P",mac:"Cmd + Shift + P",text:"Ouvrir la palette de commandes, utile avec un color picker installé."},studio:"css-colors"},
  {id:"css-typography",level:1,title:"Typographie et lisibilité",minutes:18,objective:"Styliser texte, taille, graisse, alignement et hauteur de ligne.",
    explanation:["La typographie crée une hiérarchie avant même d'ajouter des couleurs. Taille, graisse et line-height doivent travailler ensemble.","Une bonne lisibilité évite les lignes trop serrées et les contrastes faibles."],
    code:'body { font-family: system-ui, sans-serif; }\nh1 { font-size: 2rem; font-weight: 700; }\np { line-height: 1.6; }\na { text-decoration: underline; }',details:["font-family accepte une pile de polices de secours.","line-height sans unité s'adapte naturellement à la taille du texte.","text-align gère l'alignement horizontal du texte."],mistakes:["Retirer tous les soulignements de liens sans autre indice visuel.","Utiliser une line-height trop petite."],shortcut:{win:"Alt + ↑ / ↓",mac:"Option + ↑ / ↓",text:"Déplacer rapidement une déclaration ou une ligne."},studio:"css-typography"},
  {id:"css-dimensions",level:1,title:"Dimensions et largeur fluide",minutes:16,objective:"Comprendre width, height, min/max-width et pourquoi éviter les dimensions rigides partout.",
    explanation:["width fixe une largeur visée, tandis que max-width pose une limite sans empêcher l'élément de rétrécir.","Pour du contenu courant, max-width combiné à width: 100% est souvent plus robuste qu'une largeur fixe."],
    code:'.card {\n  width: 100%;\n  max-width: 360px;\n}\n.avatar { width: 96px; height: 96px; }',details:["width:100% utilise la largeur disponible.","max-width empêche une carte de devenir trop large.","height fixe peut couper du contenu si le texte grandit."],mistakes:["Forcer height sur une carte contenant du texte variable.","Oublier l'unité avec une dimension comme 300px."],shortcut:{win:"Ctrl + H",mac:"Cmd + Option + F",text:"Remplacer une valeur répétée dans le fichier."},studio:"css-dimensions"},
  {id:"css-box-model",level:1,title:"Box model : content, padding, border, margin",minutes:22,objective:"Distinguer espace intérieur et extérieur et comprendre la taille réelle d'une boîte.",
    explanation:["Chaque élément est une boîte : contenu au centre, puis padding, border et margin.","padding crée de l'air à l'intérieur ; margin sépare l'élément de ses voisins. Ce sont deux problèmes différents."],
    code:'.card {\n  padding: 24px;\n  border: 2px solid #cbd5e1;\n  margin: 20px auto;\n}',details:["Le padding fait partie de la boîte visible.","La border entoure le padding et le contenu.","La margin vit à l'extérieur de la bordure."],mistakes:["Utiliser margin pour créer de l'espace entre le texte et la bordure.","Empiler des marges aléatoires au lieu d'un système d'espacement."],shortcut:{win:"Ctrl + Shift + I",mac:"Cmd + Option + I",text:"Ouvrir les DevTools du navigateur pour inspecter le box model."},studio:"css-box-model"},
  {id:"css-background-border",level:1,title:"Fonds, bordures et arrondis",minutes:17,objective:"Créer des surfaces lisibles avec background, border et border-radius.",
    explanation:["Le fond sépare visuellement une surface de son environnement. La bordure peut renforcer cette séparation sans devenir dominante.","border-radius arrondit les coins ; il ne faut pas forcément utiliser la même valeur partout."],
    code:'.profile {\n  background-color: #ffffff;\n  border: 1px solid #e2e8f0;\n  border-radius: 16px;\n}',details:["border est un raccourci largeur/style/couleur.","background-color peint l'intérieur de la boîte.","Un radius cohérent aide à créer une identité visuelle."],mistakes:["Oublier le style dans border: 1px #ddd.","Mettre des bordures épaisses sur toutes les surfaces."],shortcut:{win:"Ctrl + D",mac:"Cmd + D",text:"Sélectionner les occurrences suivantes d'une même propriété."},studio:"css-background-border"},
  {id:"css-units",level:1,title:"px, %, rem : choisir une unité",minutes:16,objective:"Choisir entre unité fixe, relative au parent et relative à la taille racine.",
    explanation:["px est prévisible pour de petites dimensions. % dépend souvent de la taille du conteneur. rem dépend de la taille de police racine et convient bien aux espacements et tailles de texte.","Le but n'est pas d'interdire px : il faut comprendre ce qui doit rester fixe et ce qui doit s'adapter."],
    code:'.wrapper { width: 90%; max-width: 60rem; }\nh1 { font-size: 2rem; }\n.card { padding: 1.5rem; border: 1px solid #ddd; }',details:["1rem correspond à la taille de police de l'élément racine.","% est particulièrement utile pour les largeurs fluides.","Les bordures fines restent souvent très bien en px."],mistakes:["Convertir mécaniquement toutes les valeurs en rem.","Utiliser 100vw pour un bloc qui doit simplement remplir son parent."],shortcut:{win:"Ctrl + /",mac:"Cmd + /",text:"Commenter ou décommenter une ligne CSS rapidement."},studio:"css-units"},
  {id:"css-display",level:2,title:"Display : block, inline et inline-block",minutes:18,objective:"Comprendre comment display influence la place occupée et les dimensions d'un élément.",
    explanation:["display définit le comportement de base d'une boîte dans le flux. Un élément block occupe généralement toute la largeur disponible, alors qu'un élément inline reste dans la ligne de texte.","inline-block conserve un comportement en ligne tout en acceptant plus naturellement width et height. display:none retire l'élément du rendu et de la mise en page."],
    code:'.block { display: block; }\n.inline { display: inline; }\n.badge { display: inline-block; padding: .4rem .7rem; }\n.hidden { display: none; }',details:["block démarre sur une nouvelle ligne dans le flux normal.","inline suit le texte et ignore certaines dimensions de boîte.","display:none retire aussi l'espace occupé."],mistakes:["Utiliser display:none pour masquer un contenu qui doit rester accessible aux technologies d'assistance.","Attendre qu'un span inline réagisse exactement comme une boîte block."],shortcut:{win:"Ctrl + Shift + I",mac:"Cmd + Option + I",text:"Inspecter le display calculé dans les DevTools."},studio:"css-display"},
  {id:"css-box-sizing",level:2,title:"box-sizing : maîtriser les dimensions",minutes:16,objective:"Comprendre pourquoi border-box simplifie le calcul des largeurs et hauteurs.",
    explanation:["Avec content-box, width décrit uniquement la zone de contenu : padding et border s'ajoutent ensuite. Avec border-box, la largeur déclarée inclut contenu, padding et bordure.","C'est pourquoi beaucoup de projets appliquent box-sizing:border-box globalement : une boîte de 300px reste réellement une boîte externe de 300px."],
    code:'*, *::before, *::after { box-sizing: border-box; }\n.card { width: 300px; padding: 24px; border: 2px solid #94a3b8; }',details:["border-box rend les dimensions plus prévisibles.","La propriété est héritée seulement si tu construis explicitement cette stratégie.","Elle ne remplace pas une bonne compréhension du box model."],mistakes:["Croire que border-box supprime padding ou border.","Déboguer une largeur trop grande sans vérifier box-sizing."],shortcut:{win:"Ctrl + Shift + I",mac:"Cmd + Option + I",text:"Observe la taille de la boîte dans l'onglet Layout/Computed."},studio:"css-box-sizing"},
  {id:"css-position-relative",level:2,title:"Positionnement : relative et absolute",minutes:22,objective:"Créer un contexte de positionnement et placer un élément précisément sans casser la page.",
    explanation:["position:relative garde l'élément dans le flux et peut servir de repère à un descendant absolute. position:absolute retire la boîte du flux normal pour la positionner avec top/right/bottom/left ou inset.","Le parent de référence est généralement le premier ancêtre positionné. Cette relation parent/enfant est la clé pour les badges, icônes et overlays."],
    code:'.card { position: relative; }\n.badge { position: absolute; top: 12px; right: 12px; }',details:["relative sans offsets ne déplace pas visuellement la boîte.","absolute n'est pas centré automatiquement.","inset est un raccourci pour plusieurs offsets."],mistakes:["Mettre absolute partout pour construire une mise en page complète.","Oublier position:relative sur le conteneur attendu."],shortcut:{win:"F12",mac:"F12",text:"Aller à la définition d'une classe avant de modifier son positionnement."},studio:"css-position-relative"},
  {id:"css-position-fixed",level:2,title:"fixed, sticky et le défilement",minutes:20,objective:"Différencier un élément fixé au viewport d'un élément sticky lié à son conteneur.",
    explanation:["position:fixed attache généralement la boîte au viewport : elle reste au même endroit pendant le défilement. position:sticky se comporte d'abord comme une boîte normale puis se colle à un seuil comme top:0.","Sticky dépend du contexte de scroll et peut échouer si un ancêtre crée un overflow inattendu."],
    code:'.help { position: fixed; right: 20px; bottom: 20px; }\n.toolbar { position: sticky; top: 0; }',details:["fixed convient à un bouton d'aide flottant.","sticky est très utile pour les entêtes de section.","Un top/bottom est nécessaire pour donner un seuil à sticky."],mistakes:["Oublier top:0 sur un sticky.","Utiliser fixed pour une navigation qui devrait rester dans le flux sur mobile."],shortcut:{win:"Ctrl + F",mac:"Cmd + F",text:"Recherche overflow si sticky ne fonctionne pas comme prévu."},studio:"css-position-fixed"},
  {id:"css-z-index",level:2,title:"z-index et ordre d'empilement",minutes:19,objective:"Comprendre comment les éléments se superposent et pourquoi un grand z-index ne gagne pas toujours.",
    explanation:["z-index influence l'ordre de superposition des éléments positionnés et de certains contextes modernes. Mais deux éléments appartenant à des contextes d'empilement différents ne se comparent pas toujours directement.","Au début, retiens surtout : vérifie position, parent et contexte avant d'augmenter z-index à 999999."],
    code:'.card { position: relative; }\n.overlay { position: absolute; inset: 0; z-index: 2; }\n.content { position: relative; z-index: 3; }',details:["Un z-index plus grand place généralement une couche devant ses sœurs du même contexte.","transform, opacity et certaines propriétés peuvent créer de nouveaux contextes.","Le DOM reste important quand z-index est auto."],mistakes:["Empiler des z-index gigantesques au lieu de comprendre le contexte.","Oublier que le parent peut isoler l'élément dans un autre stacking context."],shortcut:{win:"Ctrl + Shift + I",mac:"Cmd + Option + I",text:"Inspecte les couches et styles calculés dans les DevTools."},studio:"css-z-index"},
  {id:"css-flex-intro",level:2,title:"Flexbox : axe principal et distribution",minutes:24,objective:"Créer un conteneur flex et répartir ses éléments sur l'axe principal.",
    explanation:["Flexbox organise les enfants directs d'un conteneur sur un axe principal. Par défaut, flex-direction:row signifie que l'axe principal est horizontal.","justify-content distribue les éléments sur l'axe principal. C'est pourquoi sa direction visuelle dépend de flex-direction."],
    code:'.nav { display: flex; flex-direction: row; justify-content: space-between; gap: 16px; }',details:["display:flex agit sur les enfants directs.","row et column changent l'axe principal.","justify-content ne veut pas toujours dire horizontal."],mistakes:["Mettre justify-content sur les enfants au lieu du conteneur.","Mémoriser horizontal/vertical sans penser à l'axe principal."],shortcut:{win:"Ctrl + Space",mac:"Ctrl + Space",text:"Afficher l'autocomplétion des valeurs Flexbox."},studio:"css-flex-intro"},
  {id:"css-flex-align",level:2,title:"Flexbox : align-items et gap",minutes:22,objective:"Aligner les éléments sur l'axe transversal et espacer proprement une interface.",
    explanation:["align-items aligne les items sur l'axe transversal. Avec flex-direction:row, cet axe est vertical ; avec column, il devient horizontal.","gap crée un espace régulier entre les enfants sans ajouter de marges aux bords du conteneur."],
    code:'.actions { display:flex; align-items:center; gap:12px; }\n.hero { display:flex; align-items:center; min-height:280px; }',details:["center est courant mais pas toujours souhaitable.","stretch est la valeur initiale dans de nombreux cas.","gap fonctionne aussi avec Grid."],mistakes:["Confondre align-items avec justify-content.","Ajouter margin-right à chaque enfant alors que gap exprime mieux l'intention."],shortcut:{win:"Alt + Click",mac:"Option + Click",text:"Créer plusieurs curseurs pour modifier des propriétés similaires."},studio:"css-flex-align"},
  {id:"css-flex-wrap",level:2,title:"Flexbox : wrap, grow, shrink et basis",minutes:26,objective:"Construire des rangées flexibles qui s'adaptent à la largeur disponible.",
    explanation:["flex-wrap autorise les items à passer à la ligne. flex-grow partage l'espace libre, flex-shrink décrit la capacité à rétrécir et flex-basis fournit une taille de départ.","Le raccourci flex combine grow, shrink et basis. Par exemple flex:1 1 220px crée des cartes flexibles avec une base de 220px."],
    code:'.cards { display:flex; flex-wrap:wrap; gap:16px; }\n.card { flex: 1 1 220px; }',details:["wrap évite de forcer toute une collection sur une seule ligne.","flex-basis est souvent plus pertinent que width pour un item flex.","min-width peut encore limiter le rétrécissement."],mistakes:["Croire que flex:1 signifie toujours la même chose dans tous les contextes.","Oublier flex-wrap puis se demander pourquoi les cartes deviennent trop étroites."],shortcut:{win:"Ctrl + D",mac:"Cmd + D",text:"Sélectionner plusieurs occurrences de .card pour refactoriser rapidement."},studio:"css-flex-wrap"},
  {id:"css-flex-page",level:2,title:"Composer une page complète avec Flexbox",minutes:28,objective:"Assembler header, navigation, hero, cartes et footer avec une stratégie de mise en page cohérente.",
    explanation:["Une page réelle utilise plusieurs petits contextes Flexbox plutôt qu'un seul grand conteneur magique. La navigation, le hero et les rangées de cartes peuvent chacun avoir leur propre axe et leurs propres règles.","Avant d'écrire CSS, identifie les groupes d'éléments qui doivent être alignés ensemble. Puis choisis flex-direction, justify-content, align-items, gap et wrap selon chaque groupe."],
    code:'.header { display:flex; justify-content:space-between; align-items:center; }\n.hero { display:flex; align-items:center; gap:32px; }\n.cards { display:flex; flex-wrap:wrap; gap:20px; }\n.card { flex:1 1 240px; }',details:["Découpe la mise en page en conteneurs locaux.","Utilise max-width et margin-inline:auto pour cadrer le contenu.","Flexbox n'empêche pas d'utiliser block pour les sections verticales normales."],mistakes:["Mettre display:flex sur body et forcer toute la page dans un seul axe.","Utiliser absolute pour aligner des zones qui devraient participer au flux."],shortcut:{win:"Ctrl + Shift + L",mac:"Cmd + Shift + L",text:"Sélectionner toutes les occurrences d'un nom de classe lors d'un refactor."},studio:"css-flex-page"}
];

function cssFiles(html, css, editableHtml) {
  return [
    {name:"index.html",readOnly:editableHtml !== true,code:'<!doctype html>\n<html lang="fr">\n<head><meta charset="utf-8"><link rel="stylesheet" href="style.css"></head>\n<body>\n'+html+'\n</body>\n</html>'},
    {name:"style.css",code:css}
  ];
}
function cssComputed(selector, property, expect, label) {
  return {expr:'getComputedStyle(document.querySelector('+JSON.stringify(selector)+')).'+property,expect:expect,label:label};
}
function cssLab(id, lesson, notion, difficulty, question, html, starterCss, solutionCss, tests, hints, explanation, retain, extra) {
  return Object.assign({id:id,path:"css",level:1,lesson:lesson,notion:notion,type:"lab",label:"Atelier CSS",difficulty:difficulty,question:question,files:cssFiles(html,starterCss),solution:cssFiles(html,solutionCss),tests:tests,hints:hints,explanation:explanation,retain:retain,live:true,previewModes:true,previewHeight:230},extra||{});
}

