  "css-flex-intro":cssFiles('<nav class="nav"><strong>Logo</strong><div>Accueil · Cours · Projets</div></nav>','.nav { display:flex; justify-content:space-between; padding:20px; background:#e0f2fe; }'),
  "css-flex-align":cssFiles('<section class="hero"><span>A</span><span>B</span><span>C</span></section>','.hero { min-height:220px; display:flex; justify-content:center; align-items:center; gap:16px; background:#f1f5f9; }\n.hero span { padding:16px; background:#bfdbfe; }'),
  "css-flex-wrap":cssFiles('<section class="cards"><article>A</article><article>B</article><article>C</article><article>D</article></section>','.cards { display:flex; flex-wrap:wrap; gap:16px; }\n.cards article { flex:1 1 180px; padding:24px; background:#dbeafe; }'),
  "css-flex-page":cssFiles('<header class="header"><strong>Logo</strong><nav>Cours · Projets</nav></header><section class="hero"><div><h1>Flexbox</h1><p>Compose la page.</p></div><button>Commencer</button></section><section class="cards"><article>A</article><article>B</article><article>C</article></section><footer>Footer</footer>','.header,.hero { display:flex; justify-content:space-between; align-items:center; gap:24px; padding:20px; }\n.cards { display:flex; flex-wrap:wrap; gap:16px; padding:20px; }\n.cards article { flex:1 1 180px; padding:24px; background:#e0f2fe; }\nfooter { display:flex; justify-content:center; padding:20px; }')
