function cssLessonsForLevel(level){ return CSS_LESSONS.filter(l=>l.level===Number(level)); }
function cssExercisesForLevel(level){ return CSS_EXERCISES.filter(e=>e.level===Number(level)); }
function cssExercisesForLesson(id){ return CSS_EXERCISES.filter(e=>e.lesson===id); }
function cssEvaluationForLevel(level){ return CSS_EVALUATIONS[Number(level)]||[]; }
function cssProjectForLevel(level){ return CSS_PROJECTS.find(p=>p.level===Number(level)); }
